416	\begin{lemma}[Formalization support for the binary-measurement distance]
417		\label{lem:binary-measurement-distance}
418		\lean{MIPStarRE.QPBT.binaryObservableEffect}
419		\lean{MIPStarRE.QPBT.binaryObservableDistSq}
420		\lean{MIPStarRE.QPBT.binaryObservableDistSq_eq_stateDepDistSq_div_two}
421		\lean{MIPStarRE.QPBT.stateDepDistSq_eq_two_sub_two_mul_correlation}
422		\lean{MIPStarRE.QPBT.binaryObservableDistSq_eq_one_sub_correlation}
423		\leanok
424		\uses{def:povm-conventions}
425		This is not a named statement of \cite{Natarajan2017Linearity}; it records
426		the normalization discussed in
427		Remark~\ref{rem:linearity-distance-normalization}. For operators $S$, $T$
428		and $\rho$ on $\hilb$, write
429		$d_\rho(S,T)^2 = \Re \Tr\big((S-T)^\dagger (S-T) \, \rho\big)$ and
430		$P_S^\pm = (\Id \pm S)/2$ for the affine operators that are effects of a
431		binary projective measurement when $S$ is a binary observable, and set
432		$d^{\mathrm{bin}}_\rho(S,T)^2
433		= \sum_{s \in \{+,-\}} d_\rho(P_S^s, P_T^s)^2$. Then, with no hypothesis
434		on $S$, $T$ or $\rho$,
435		\[
436			d^{\mathrm{bin}}_\rho(S,T)^2 = \tfrac{1}{2} \, d_\rho(S,T)^2 .
437		\]
438		If moreover $S$ and $T$ are binary observables and $\rho$ is a density
439		operator, then
440		\[
441			d_\rho(S,T)^2 = 2 - 2 \Re \Tr(S T \rho) ,
442			\qquad
443			d^{\mathrm{bin}}_\rho(S,T)^2 = 1 - \Re \Tr(S T \rho) .
444		\]
445	\end{lemma}
446	\begin{proof}
447		\leanok
448		Expand $P_S^s - P_T^s = \pm (S - T)/2$ in each of the two outcomes and
449		sum; this uses no hypothesis on $S$, $T$ or $\rho$. The two correlation
450		identities use $S^2 = T^2 = \Id$, $\Tr \rho = 1$, and the Hermiticity of
451		$S$, $T$ and $\rho$.
452	\end{proof}
