409		\leanok
410		\uses{lem:boolean-characters}
411		Orthogonality of the characters of $\F_2^t$ gives the inversion formula;
412		the Parseval identity follows by substituting it into the product and
413		exchanging the two sums; the last identity uses $O(a)^2 = \Id$.
414	\end{proof}
